    source:
      '#!/usr/bin/env bun\n/**\n * Simple inline mode test\n */\n\nimport React, { useState, useEffect } from "react"\nimport { render, Box, Text, useApp, createTerm } from "silvery"\nexport const meta: ExampleMeta = {\n  name: "Inline Simple",\n  description: "Inline rendering from current cursor position",\n  features: ["render() inline mode", "one-shot output"],\n}\n\nfunction Counter() {\n  const { exit } = useApp()\n  const [count, setCount] = useState(0)\n\n  useEffect(() => {\n    const timer = setInterval(() => {\n      setCount((c) => {\n        if (c >= 5) {\n          clearInterval(timer)\n          return c\n        }\n        return c + 1\n      })\n    }, 500)\n\n    return () => clearInterval(timer)\n  }, [])\n\n  // Exit cleanly after count reaches 5\n  useEffect(() => {\n    if (count < 5) return\n    const timeout = setTimeout(() => exit(), 300)\n    return () => clearTimeout(timeout)\n  }, [count, exit])\n\n  return (\n    <Box>\n      <Text>Count: {count}</Text>\n    </Box>\n  )\n}\n\nasync function main() {\n  console.log("Before\\n")\n\n  using term = createTerm()\n  const { waitUntilExit } = await render(<Counter />, term, {\n    mode: "inline",\n  })\n\n  await waitUntilExit()\n\n  console.log("\\nAfter")\n}\n\nif (import.meta.main) {\n  main().catch(console.error)\n}\n',
